function nodeLink(n,label){return [5,6,7,10].includes(n.id)?composeAnchor(n.id,label):link(n.page,label);}
function objective(){const next=D.nodes.find(n=>!state.solved[n.id]);return next?`<p>${nodeLink(next,'继续核对：'+next.title)}。提示由你主动展开，公开资料可以按自己的顺序读。</p>`:'<p>事实核对已完成，可回最后对话作决定，或查便笺中的原件。</p>';}
function help(){return `<header class="help-manual-title"><span>操作手册 / 随时可返回材料</span><h1>阅读与提示</h1></header><p>本作品含遗体、受困身体与身份替代主题，无声音、闪烁或倒计时。人物、机构与账户均为虚构，网站操作在当前浏览器中模拟，不会向真实收件人发送邮件或留言。</p><div class="help-routing"><p>回水宾馆服务记录是最初入口。材料中列出的引用说明下一份材料为什么有关；跨站链接标出站名，照片返回原记录，已读出处会留在便笺。公开站点可以自由查阅。回信可以简写事实要点，也可以展开引用表述。三晚的日期分别记入，搬床安排可以调整先后；另外想说的话可以自行填写。</p>${objective()}</div><section class="help-current"><h2>当前可以核对的问题</h2><ul class="list">${D.nodes.filter(n=>!state.solved[n.id]&&n.deps.every(q=>state.solved[q])).map(n=>`<li>${nodeLink(n,n.title)} · 可在这处操作主动展开三级提示</li>`).join('')}</ul></section><div class="help-appendices"><section><h2>授权资料</h2><p>家庭卷使用玉枝给出的“蓝线袖口”；张岚附件使用领取函中的“ZL-0816”。需要返回授权来源时，资料页会保留入口。</p></section><section><h2>照片与存档</h2><p>拆检一次只看一张，按附件顺序推进；普通照片不自动全屏。原图查看有放大、缩小与复位，手机可在放大后滑动照片；键盘可以用加减键和方向键，Escape返回原入口。</p><p>刷新保留已经填写的记录和阅读位置。同一网站的页面在当前标签中打开；前往另一个网站时，新建标签页。可以使用浏览器的前进、后退与中键操作。从同一个作品入口打开，各个页面会共用当前浏览器中的进度。</p>${link('strategy','独立攻略（默认折叠答案）')}</section></div>`;}
function strategy(){return `<header class="strategy-title"><span>按需展开 / 含剧透</span><h1>独立攻略</h1></header><nav class="strategy-jump" aria-label="问题索引">${D.nodes.map(n=>`<a href="#answer-${n.id}">${n.id}</a>`).join('')}</nav><p>按问题展开，仅打开需要的部分。下方结局说明另行折叠；使用提示不影响成就。</p>${D.nodes.map(n=>`<details id="answer-${n.id}"><summary>${n.id}. ${E(n.title)}</summary><p>${nodeLink(n,'回到这处操作')}</p><ol>${n.fields.map(f=>`<li>${E(f.label)}：${E(f.answer)}</li>`).join('')}</ol><p>${E(n.result)}</p>${n.id===11?'<p>通过材料核对后，还需分别送出袁、陈的身体位置，等本人反馈，再前往最后一组。</p>':''}</details>`).join('')}<details><summary>三项生活调查</summary><p>押金退还200元，老胡仍欠20元；雨衣A、棉袄B、窗帘C；相册按拍摄日期A、B、C。</p></details><details><summary>最后的正式决定与结局操作（剧透）</summary><p>主结局选择取回身体，确认自己归还，再撤宋、林、母亲三份床首纸签，最后真正醒来，阅读清晨、回信与早餐。母亲寄留结束。另一选择让母亲代自己离开，自己留在B-0306，进入同住。结局页可回退选择，调查不用重做。</p></details>`;}
function author(){return `<header class="author-closing"><span>abc / 写在最后</span><h1>谢谢你陪知遥走到这里</h1></header><article class="article"><p>谢谢你陪知遥查完这些床、照片和没有写完的记录。她终于知道母亲来过，也知道有人为那次来访等了很久，这些事不能互相抵消；若你愿意，可以回去看看衣铺和街坊的生活留言，那里还有几件母亲没有做完的小事，不是为了留下她，只是让她被记得更完整一些。</p><p>abc · 原创故事与网页作品。照片是为虚构事件制作的图像，文字记录以可读排版生成，不来自真实患者或案件。</p></article><section class="author-readings"><h2>已经留下的阅读记录</h2><ul class="list">${C.achievements.map(([name,fn],i)=>{const yes=fn(state);return `<li>${yes?E(name):i===4||i===11?'未完成的生活调查':'尚未显示的记录'}<small>${yes?'已达成 · '+new Date(state.achievementDates[i]).toLocaleDateString('zh-CN'):'具体真相条件暂不显示'}</small></li>`;}).join('')}</ul></section><div class="actions">${link('p15','回街坊账目')}${link('p26','回衣铺照片')}${link('strategy','完整攻略')}<button type="button" data-rewind>返回正式决定之前</button></div><details><summary>参考与创作说明</summary><p>阅读组织参考《逾洲往事》，人物关系与迟来的理解参考鲁迅《故乡》《风筝》的事件组织，伪装的可见行动参考《画皮》。人物、机制、文案与素材另行原创。主线不需要阅读外部资料。</p><p><a href="https://miyeji.cn/games/yu-zhou-wang-shi" target="_blank" rel="noopener noreferrer">《逾洲往事》介绍</a></p></details>`;}
function settings(){return `<header class="settings-title"><span>当前浏览器 / 本作品</span><h1>阅读设置与存档</h1></header><section class="settings-preferences"><p>偏好只保存在当前浏览器。作品不读取真实身份、联系人或摄像头。</p>${[['static','静态效果模式']].map(([k,l])=>`<p><label><input type="checkbox" data-pref="${k}" ${state.prefs[k]?'checked':''}> ${l}</label></p>`).join('')}<p>系统减少动画偏好同样有效。作品的资料不会因效果模式改变，提示与辅助描述均不影响成就。</p></section><section class="settings-backup"><h2>进度备份</h2><div class="actions"><button type="button" id="export-save">导出存档</button><label>导入本作品存档 <input type="file" id="import-save" accept=".json,application/json"></label></div><p id="save-feedback" role="status"></p></section><section class="settings-reset"><h2>清除进度</h2><p>清除会移去本次答案、已读出处、个人备注与结局记录，其他作品的存档不会受影响。请先导出备份。</p><form id="reset-form"><label>输入“清除进度”再确认 <input name="confirm" autocomplete="off" required></label><button type="submit">清除本作品进度</button></form><p id="reset-feedback" role="status"></p></section>`;}
function searchPage(){const query=new URLSearchParams(location.search).get('q')||'',results=C.search(D.pages,query,state.read,state.access,state);return `<header class="search-title"><span>已出现的出处 / 全文检索</span><h1>查找已出现的材料</h1></header><form class="searchbox" action="${ROOT}search.html"><label class="sr-only" for="search-input">人名、旧地名或物件号</label><input id="search-input" name="q" value="${E(query)}" placeholder="人名、旧地名、床台号"><button type="submit">搜索</button></form><p>支持袁老师、床箱、三一二等已出现称呼。范围为公开资料、已授权附件与已经经历的联系；尚未领取的私人全文不会进入搜索结果。</p>${query&&results.length?`<ul class="list">${results.map(x=>`<li>${link(x.id,sites[x.site][0]+' · '+x.title)}<small>${E(x.date)}</small></li>`).join('')}</ul>`:query?'<p>没有匹配。可查袁志强、陈慧、梁秀琴、张岚、河沿路、B-0312、床台。也可以先从各站公开目录进入。</p>':'<p>先输入已经看到的人名或编号，不需要猜作者的唯一词语。</p>'}${link('help','返回当前调查问题')}`;}
function readingTools(){return `<details class="work-menu" data-work-ui><summary>作品选项</summary><nav>${link('notes','调查便笺')} ${link('search','材料检索')} ${link('help','操作与提示')} ${link('settings','存档设置')}<button type="button" data-motion-toggle aria-pressed="${state.prefs.static}">${state.prefs.static?'已静止':'暂停动态'}</button></nav></details>`;}
function siteMenu(site){
 const entries={hotel:[['p01','首页'],['p02','客房与价格'],['hotel-directions','交通与到店'],['p03','住客留言'],['p07','老店迁址'],['hotel-contact','联系前台']],forum:[['p09','街坊与住客'],['p15','小店往来'],['forum-search','搜索主题']],paper:[['p16','历史版'],['p17','地方报道'],['p18','名单补刊'],['p20','旧街特写'],['paper-search','版面检索']],store:[['p21','接收目录'],['store-search','编号查询'],['p22','签领附件'],['p23','返库记录']],album:[['p25','底片卷目'],['p26','衣铺'],['p27','旧街'],['p28','家信'],['p30','补洗卷']],hospital:[['p31','患者服务'],['p32','授权须知'],['hospital-request','领取资料']]};
 return (entries[site]||[]).filter(([id])=>!byId[id]||offered(byId[id])).map(([id,label])=>localNav(id,label)).join('');
}
function top(site){
 if(site==='store'&&privateFiles.includes(P))return `<header class="attachment-reader-head"><div><small>镇西签领附件 / 持有人提供</small><strong>${E(p.title)}</strong></div><nav>${link('p21','公开接收目录')}${link('notes','自己的便笺')}</nav></header>`;
 const menu=`<nav class="platform-menu" aria-label="栏目">${siteMenu(site)}</nav>`;
 if(site==='message')return `<header class="mail-brand">${link('mail-inbox','回水邮局')}<span>网页邮件</span><small>许知遥 &lt;xu.zhiyao@huishui.example&gt;</small></header><nav class="mail-toolbar" aria-label="邮件操作"><button type="button" data-mail-new>写信</button>${link('mail-inbox','收件箱')}${link('mail-attachments','附件管理')}<form class="mail-search" action="${E(href('mail-inbox'))}"><label class="sr-only" for="mail-query">搜索邮件</label><input id="mail-query" name="q" placeholder="搜索发件人、主题" value="${E(new URLSearchParams(location.search).get('q')||'')}"><button type="submit">搜索</button></form></nav>`;
 if(site==='phone')return `<header class="phone-head">${link('phone-contacts','联系')}<strong>${P==='p42'?'袁志强、陈慧':P==='p36'?'沈梁':P==='phone-thread'?({yuzhi:'陈玉枝',shen:'沈梁',zhang:'张岚',yuan:'袁志强',chen:'陈慧'}[new URLSearchParams(location.search).get('contact')]||'消息'):'消息'}</strong><small>许知遥</small></header>`;
 if(site==='scene')return '';
 if(site==='author')return `<header class="utility-brand">${link('entry','梦演（魇）时分')}<span>${{notes:'随身便笺',help:'操作与提示',strategy:'攻略 / 含剧透',author:'abc的回信',settings:'阅读与存档',search:'材料检索'}[P]||''}</span></header>`;
 if(site==='hotel')return `<header class="hotel-mast"><div><small>新桥路28号 / 原河沿路老店</small>${link('p01','回水宾馆')}<p>干净铺盖　价格实在　单床128元起</p></div><div class="hotel-frontdesk"><strong>到店前请先联系</strong>${link('hotel-contact','前台留言 / 客房咨询')}<span>三楼无电梯，长辈入住请提前说明</span></div></header>${menu}<p class="hotel-bulletin"><b>前台通知</b>312房暂停接单；老客请认新桥路新址。${link('p08','查看前台说明')}</p>`;
 if(site==='forum')return `<div class="forum-session"><span>欢迎，许知遥</span>${link('forum-search','站内搜索')}</div><header class="forum-mast">${link('p09','回水生活')}<p>搬到新街，老帖还在。</p></header>${menu}<div class="forum-location"><span>街坊交流 · 店铺往来 · 住客留言</span><span>发帖前请保留当事人的原话与日期</span></div>`;
 if(site==='paper')return `<div class="press-topline"><span>地方新闻 / 回水镇</span>${link('paper-search','查找旧版')}</div><header class="newspaper-mast"><span>回水镇地方版</span>${link('p16','回水周报')}<small>历史资料室<br>原刊与后续更正分别留存</small></header>${menu}`;
 if(site==='store')return `<header class="records-mast"><div><small>镇西临时保管点</small>${link('p21','旧物接收登记')}<span>接收、签领与返库记录</span></div><form action="${E(href('store-search'))}"><label for="registry-query">物件编号</label><input id="registry-query" name="q" placeholder="如 B-0312"><button type="submit">查询</button></form></header>${menu}`;
 if(site==='album')return `<header class="family-mast"><small>陈玉枝 / 分享给知遥</small>${link('p25','许家的相册')}<span>四卷底片，还有几张后来补洗的照片</span></header>${menu}`;
 if(site==='hospital')return `<div class="hospital-service-line"><span>回水市医院 · 患者服务</span><span>资料领取须本人授权</span></div><header class="hospital-mast">${link('p31','回水市医院')}<span>历史资料复制服务</span>${link('hospital-request','凭授权领取资料')}</header>${menu}`;
 return '';
}
function mailFolders(){
 const unread=receivedMail().filter(x=>x.id!=='entry'&&!state.read[x.id]).length;
 return `<aside class="mail-folders"><h2>我的邮箱</h2><nav aria-label="邮件文件夹">${localNav('mail-inbox','收件箱'+(unread?' ('+unread+')':''))}${localNav('mail-drafts','草稿箱')}${localNav('mail-sent','已发送')}${localNav('mail-attachments','附件管理')}${localNav('mail-trash','已删除草稿')}</nav><p>许知遥<br><small>私人邮件</small></p></aside>`;
}
function nativeShell(site,html){
 const layout=D.design?.[P]?.layout||P;
 const main=`<main id="main" class="${P==='entry'?'mail-page entry-letter':site+'-page'} ${isCompose()?'compose-page inbox-page':''} document-${P} ${!p?'support-'+P:''}" data-layout="${isCompose()?'reply-'+p.q:layout}">${p&&!isCompose()?breadcrumbs(p):''}${html}</main>`;
 if(site==='message')return `<div class="mail-workspace">${mailFolders()}${main}</div>`;
 if(site==='hotel')return `<div class="hotel-site-body">${main}<aside class="hotel-service-index"><h2>住店服务</h2>${link('p03','留言与前台回复')}${link('p04','房务维修留档')}${link('p06','采购与移交留档')}${link('p07','旧址与房号沿用')}<p>老物件的来处，前台留有接收记录。需要查票据，请带上房号和登记号。</p><h2>到店提醒</h2><p>14时后入住<br>12时前退房<br>街口公共停车位<br>早餐隔壁自理</p>${link('hotel-directions','查看交通说明')}</aside></div>`;
 if(site==='hospital')return `<div class="hospital-site-body"><aside class="patient-menu"><h2>资料服务</h2>${link('p31','办理须知')}${link('p32','本人授权函')}${link('hospital-request','资料领取')}${link('p33','护理记录与补记')}${link('p34','家属另附材料')}<p>私人材料仅限授权收件人查看。</p></aside>${main}</div>`;
 return main;
}
function footer(site){
 const text=site==='store'&&privateFiles.includes(P)?'私人附页 / 沈万海留存 / 本次分享给许知遥 / 不编入公开接收目录':{hotel:'回水宾馆 / 新桥路28号 / 住店服务以到店确认为准',forum:'回水生活 / 旧帖保留原日期，编辑与补记另列',paper:'回水周报 / 地方版资料室 / 原刊署名与日期保留',store:'镇西旧物保管点 / 编号沿用原登记，不作为现址证明',album:'陈玉枝的家庭相册 / 本次分享仅供许知遥查看',hospital:'回水市医院 / 资料复制服务 / 授权范围内查看',message:'回水邮局 / 私人网页邮件',phone:'许知遥 / 联系记录',scene:''}[site]||'';
 return `${text?`<footer class="native-footer footer-${site}">${E(text)}</footer>`:''}<div class="work-options" data-work-ui>${readingTools()}${saveWarning?'<p role="status">进度暂未持久保存，请导出备份。</p><button type="button" id="export-session">导出当前进度</button><p id="session-feedback" role="status"></p>':''}</div>`;
}
function photoHtml(id){
 const im=D.images[id];if(!im)return '<p>原图记录缺失，请回来源页。</p>';const site=displayedPlatform(),credit=`<small class="photo-credit">${E(im.source)} · ${E(im.date)}</small>`;
 const caption=site==='scene'?`<details class="scene-photo-source"><summary>原照出处</summary><p>${E(im.caption)}</p>${credit}</details>`:site==='album'?`<span class="album-caption">${E(im.caption)}</span>${credit}`:site==='hotel'?`<span class="room-photo-caption">${E(im.caption)}</span>${credit}`:`<span>${E(im.caption)}</span>${credit}`;
 return `<figure class="evidence-photo photo-${site}" data-image="${id}"><button type="button" class="photo-open" data-zoom="${id}" aria-label="查看原图：${E(im.source)}"><img src="${ROOT}assets/${id}.${im.ext}?v=20261011v11" alt="${E(im.alt)}" width="${im.width}" height="${im.height}" ${im.critical?'fetchpriority="high"':'loading="lazy"'} decoding="async"></button><div class="image-error" hidden><p>图片未能加载，可重试或阅读相同范围的说明。</p><button type="button" data-retry="${id}">重试</button><p>${E(im.alt)}</p></div><figcaption>${caption}</figcaption><details class="visual-description" ${site==='scene'?'data-work-ui':''}><summary>照片文字与说明</summary><p>${E(im.alt)}</p>${im.transcript&&im.transcript!==im.alt?`<p>${E(im.transcript)}</p>`:''}</details></figure>`;
}
function documentRows(rows,caption=''){return `<div class="table-scroll" tabindex="0" role="region" aria-label="${E(caption||'原件登记')}，可横向滚动"><table class="document-register">${caption?`<caption>${E(caption)}</caption>`:''}<tbody>${rows.map(([label,value])=>`<tr><th scope="row">${E(label)}</th><td>${E(value)}</td></tr>`).join('')}</tbody></table></div>`;}
function printLeaves(page,labels){return `<div class="print-leaves">${page.images.map((id,i)=>`<section class="print-leaf"><header><span>${E(labels[i])}</span><small>${E(D.images[id].date)}</small></header>${photoHtml(id)}${para(page.body.slice(i,i+1))}</section>`).join('')}</div>`;}
function albumRolls(){return ['p26','p27','p28','p30'].map((id,i)=>{const page=byId[id];return `<li><div class="roll-number">${i<3?'0'+(i+1):'补洗'}</div><div class="roll-photo">${routeAnchor(href(id),page.title,'album')}<figure><a href="${E(href(id))}" target="_self" aria-label="打开${E(page.title)}"><img src="${ROOT}assets/${page.images[0]}.${D.images[page.images[0]].ext}" width="${D.images[page.images[0]].width}" height="${D.images[page.images[0]].height}" loading="lazy" decoding="async" alt="${E(D.images[page.images[0]].alt)}"></a></figure></div><div class="roll-notes"><p>${E(['衣铺里留下的近照，雨衣的袖口还没收好。','搬走以前的河沿路，后来留在房间里的柜子。','母亲写回家的信，玉枝没有丢。','相馆的补洗章与照片拍摄日分开记。'][i])}</p><small>${E(page.date)}</small></div></li>`;}).join('');}

function pics(page){
 if(!page.images.length)return '';
 if(page.id==='p05'){const ix=Math.min(state.pictures.p05||0,page.images.length-1);return `<div class="inspection" id="pictures"><nav class="attachment-turn" aria-label="拆检附件顺序"><span>W-1008 / ${ix+1} / ${page.images.length}</span>${ix>0?'<button type="button" data-pic-step="-1">上一张</button>':''}${ix<page.images.length-1?'<button type="button" data-pic-step="1">下一张附件</button>':''}</nav>${photoHtml(page.images[ix])}<p class="attachment-return">${link('p04','回周师傅的原记录')} · ${link('p06','查这件床台的来源')}</p></div>`;}
 return `<div class="originals originals-${page.images.length}">${page.images.map(photoHtml).join('')}</div>`;
}
function related(page){
 const ids=page.links.filter(id=>offered(byId[id]));if(!ids.length)return '';
 const label={hotel:'留档出处',forum:'帖内引用',paper:'原刊互见',store:'簿内索引',album:'玉枝另附',hospital:'原记录与附件',message:'引用的材料',scene:'仍可打开的联系'}[page.site];
 return `<nav class="source-citations citations-${page.site}" aria-label="${label}"><span>${label}：</span>${ids.map(id=>{const target=platformOf(id),brand=target==='phone'?'联系':sites[target]?.[0]||'';return link(id,(target!==displayedPlatform()&&brand?brand+' / ':'')+byId[id].title);}).join('<span class="citation-separator">；</span>')}</nav>`;
}
