function fieldHtml(n,field,i,mode){
 const key=`q${n.id}_${i}`,saved=state.drafts[key]||'',draft=saved;
 if(n.id===7&&i===0)return sequenceField(n);
 if(n.id===10&&i===0)return orderField(n);
 if(n.id===12&&(i===0||i===2)){const ready=i===0?state.returns.yuan&&state.returns.chen:true;return `<div class="record-field observed-state" data-field="${i}"><span>${E(field.label)}</span><output>${i===0?(ready?'袁志强、陈慧均已亲自回话':'尚未收到两人的回话'):'撤下凭据以后，母亲不能再借用他人的身体'}</output><input type="hidden" name="f${i}" value="${ready?E(field.answer):''}"></div>`;}
 const select=`<select id="${key}" name="f${i}" data-draft="${key}" required><option value="">请选择</option>${field.options.map(v=>`<option value="${E(v)}" ${draft===v?'selected':''}>${E(v)}</option>`).join('')}</select>`;
 if(mode==='dispatch')return `<fieldset class="record-field dispatch-fact" data-field="${i}"><legend>${E(field.label)}</legend>${field.options.map((v,j)=>`<label><input type="radio" name="f${i}" value="${E(v)}" data-draft="${key}" ${draft===v?'checked':''} required><span>${E(v)}</span></label>`).join('')}</fieldset>`;
 if(['note','reply','letter'].includes(mode))return `<div class="record-field note-line" data-field="${i}"><label for="${key}">${E(field.label)}</label><input id="${key}" name="f${i}" data-draft="${key}" value="${E(draft)}" maxlength="400" placeholder="写事实要点，可以简写" required autocomplete="off"><details class="source-wording"><summary>引用记录中的表述</summary><ul>${field.options.map(v=>`<li><button type="button" data-fill="${key}" data-value="${E(v)}" aria-pressed="${draft===v}">${E(v)}</button></li>`).join('')}</ul></details></div>`;
 return `<div class="record-field ${mode}-line" data-field="${i}"><label for="${key}">${E(field.label)}</label>${select}</div>`;
}
function answerValue(field,value){const clean=s=>String(s).normalize('NFKC').toLowerCase().replace(/[\s，,、。.;；：:()（）-]/g,'');return [field.answer,...(field.aliases||[])].find(v=>clean(v)===clean(value))?field.answer:field.options.find(v=>clean(v)===clean(value))||value;}
function sequenceField(n){
 const old=state.drafts.q7_0===n.fields[0].answer,labels=['开始借用','到学校','回位并归还'],defaults=['12','13','15'],days=labels.map((_,i)=>state.drafts['q7_seq'+i]||(old?defaults[i]:''));
 return `<fieldset class="record-field chronology-field" data-field="0"><legend>2012年8月 / 按原件记回三个日子</legend><input type="hidden" id="q7_0" name="f0" data-draft="q7_0" value="${E(state.drafts.q7_0||'')}"><ol>${labels.map((label,i)=>`<li><label for="q7-seq-${i}">${label}</label><select id="q7-seq-${i}" data-draft="q7_seq${i}" data-sequence="${i}" required><option value="">日期</option>${['12','13','14','15','16'].map(d=>`<option value="${d}" ${days[i]===d?'selected':''}>8月${d}日</option>`).join('')}</select></li>`).join('')}</ol></fieldset>`;
}
function readOrder(){const saved=state.drafts.q10_order;if(['return,release','release,return'].includes(saved))return saved.split(',');return state.drafts.q10_0===D.nodes[9].fields[0].answer?['return','release']:['release','return'];}
function orderField(n){const order=readOrder(),text={return:'先让活着的人认回并取回自己的身体',release:'解除死者的寄留，撤下床首凭据'};return `<fieldset class="record-field order-field" data-field="0"><legend>改好安排，再发给沈梁</legend><input type="hidden" id="q10_0" name="f0" data-draft="q10_0" value="${E(order[0]==='return'?n.fields[0].answer:'先撤凭据，谁还在都以后再说')}"><ol>${order.map((key,i)=>`<li><span>${E(text[key])}</span><button type="button" data-order="${key}" data-direction="${i===0?1:-1}" aria-label="${E(text[key])}，${i===0?'下移':'上移'}">${i===0?'下移':'上移'}</button></li>`).join('')}</ol></fieldset>`;}
function updateSequence(form){const values=[0,1,2].map(i=>form.querySelector('[data-sequence="'+i+'"]').value),value=values.join(',')==='12,13,15'?D.nodes[6].fields[0].answer:values.every(Boolean)?'8月'+values[0]+'日借用，'+values[1]+'日到校，'+values[2]+'日归还':'';form.elements.f0.value=value;commit('draft',{key:'q7_0',value});}

function replyText(id){
 return {1:'我查的是木制床台，不是新换的床垫。采购票写的是床垫和铺盖；旧物票里的B-0312在2014年转来，现在仍放在312。两张票的编号和房号对应都附上了，请别再用换过铺盖回答这件事。',2:'周师傅，我查到的是当前312的B-0312。床脚缺角、长侧板卸下的位置和右边的柜子都能对上，2014年的尺寸和维修记录也一致。我把旧物票留着，原单请别改成紧螺丝结单。',3:'周敏，我把你记下的几句话同旧资料对过了。志强教书十多年，没有驾驶证；他说的货运经历和旧货站31号，都不属于他过去的生活。变化是在9月20日至22日住店以后出现的。我把原话和日期附在这里，先别把它们改成别人猜的说法。',4:'陈恪，两家日期我分开记了：袁老师是今年9月20日住店、22日回来；你母亲是2019年6月11日去、13日回家，15日说起陌生的护理用语。相隔这些年，不能只凭照片说是一回事，但货运和护理经历都有旧资料可以继续查。',5:'玉枝阿姨，补充名单里，我和你已经撤离、登车，宋大勇和林素秋后来确认遇难。母亲那一栏没有遗体核验，当时仍是失联。我不把这几个名字算成同一种结果；你留下的相册，我还想接着看。',6:'张岚，学校门口那张照片里的身体是你23岁时的身体，相机也是你的。8月13日是另一位家长代拍。背面的“遥遥”、蓝线袖口和柜子细节，同母亲的原信对应。我想问清那次来访，也想知道你后来怎么样了。',7:'张岚，我把时间记清了：12日开始借用，13日到学校，15日夜回位后归还。你的自述和沈万海另记的日期能够互相对照。身体重新对应以后，仍可能留在梦中；真正醒来还要确认手能不能按自己的意思动。我会把你等过的三个晚上一起留下。',10:'沈梁，先别搬原床位，也别拆床首的签。张岚2012年的归还、2013年撤签和2016年那张旁页，写的顺序不是你刚才说的那样。先让活着的人取回自己的身体，再解除死者的寄留联系；两件事不能颠倒。'}[id]||'';
}
function nodeHtml(id){
 const n=D.nodes.find(x=>x.id===id);if(!n)return '';const done=state.solved[id],mode=[1,2].includes(id)?'ticket':[3,4].includes(id)?'reply':id===9?'ledger':id===11?'dispatch':[8,12].includes(id)?'note':'letter';
 const headings={1:'前台补件留言',2:'维修单W-1008 / 补记',3:'回复周敏',4:'回复陈恪',5:'收件人：陈玉枝',6:'收件人：张岚',7:'收件人：张岚',8:'我得把这几件事写清楚',9:'归还栏 / 补核',10:'收件人：沈梁',11:'分别发给袁与陈',12:'自己的位置，最后再看一眼'};
 const receipt={1:'前台 / 留言已留存',2:'周师傅 / 补记已送达',3:'许知遥 / 回复已留存',4:'许知遥 / 回复已留存',5:'许知遥 → 陈玉枝',6:'许知遥 → 张岚',7:'许知遥 → 张岚',8:'知遥的晨间便笺',9:'补核留存 / 原簿不改',10:'许知遥 → 沈梁',11:'材料核对完成',12:'知遥 / 最后一次核对'};
 let fields=n.fields.map((f,i)=>fieldHtml(n,f,i,mode)).join('');
 if(id===9)fields=`<table class="ledger-inputs"><caption>物件、活体与原件依据</caption><tbody>${n.fields.map((f,i)=>`<tr class="ledger-check-line"><th scope="row">${i<3?['B-0312','B-0211','B-0306'][i]:'依据 '+(i-2)}</th><td>${fieldHtml(n,f,i,mode)}</td></tr>`).join('')}</tbody></table>`;
 if(id===11)fields=`<div class="dispatch-yuan"><h3>袁志强 / 镇西家中</h3>${n.fields.slice(0,2).map((f,i)=>fieldHtml(n,f,i,mode)).join('')}</div><div class="dispatch-chen"><h3>陈慧 / 镇南家中</h3>${n.fields.slice(2,4).map((f,i)=>fieldHtml(n,f,i+2,mode)).join('')}</div><div class="dispatch-owner">${fieldHtml(n,n.fields[4],4,mode)}</div>`;
 const note=mode==='letter'||mode==='reply'?`<label class="personal-remark" for="reply-note-${id}">另外想说的话<textarea id="reply-note-${id}" data-note="reply${id}" rows="4" maxlength="5000" placeholder="写给对方的话">${E(state.notes['reply'+id]||'')}</textarea></label>`:'';
 const body=done?`<div class="sent-record"><p class="sent-stamp">${E(receipt[id])}</p>${replyText(id)?`<p class="posted-reply">${E(replyText(id))}</p>`:''}<p class="completed">${E(n.result)}</p>${state.notes['reply'+id]?`<p class="personal-remark-copy">${E(state.notes['reply'+id])}</p>`:''}${link(n.go,byId[n.go].title)}</div>`:`<p class="record-intent">${E(n.context||'')}</p><form data-node-form="${id}" class="record-form form-${mode}">${fields}${note}<button class="send-record" type="submit">${E(n.submit||'确认')}</button></form>`;
 const hint=`<details data-work-ui class="hint"><summary>需要一点提示</summary><button type="button" data-hint="${id}" ${(state.hints[id]||0)>=3?'disabled':''}>${(state.hints[id]||0)>=3?'提示已全部展开':'下一层提示'}</button><div data-hint-content="${id}">${n.hints.slice(0,state.hints[id]||0).map((h,i)=>`<p>${i+1}. ${E(h)}</p>`).join('')}</div></details>`;
 return `<section class="record-action action-${mode}" data-node="${id}" data-operation="${mode}"><h2 tabindex="-1">${E(headings[id])}</h2>${body}<p class="feedback" data-feedback="${id}" role="status" aria-live="polite"></p>${hint}</section>`;
}

